export function getResourceGuidance(id, terms) {
  const item = guidance[id]
  return {
    ...item,
    importantTerms: terms.map((term) => ({ term, definition: termDefinitions[term] ?? 'A useful concept to understand while learning this resource.' })),
  }
}
